// Title: Have A Nice Day!
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // Normalize pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    // Center coordinates and adjust aspect ratio
    vec2 centeredUV = (uv - 0.5) * 2.0;
    centeredUV.x *= iResolution.x/iResolution.y;

    // Start with white background
    vec3 col = vec3(1.0);

    // Draw black head
    float head = length(centeredUV);
    if (head < 0.7) col = vec3(0.0);

    // Draw eyes
    vec2 leftEyePos = centeredUV - vec2(-0.25, 0.2);
    vec2 rightEyePos = centeredUV - vec2(0.25, 0.2);
    float leftEye = length(leftEyePos);
    float rightEye = length(rightEyePos);

    // 130 BPM timing
    float blink = step(0.9, sin(iTime * 2.167 * 3.14159));

    // Both eyes with X blink
    if (blink > 0.5) {
        // Create X shapes
        if (min(abs(leftEyePos.x - leftEyePos.y), abs(leftEyePos.x + leftEyePos.y)) < 0.03 
            && max(abs(leftEyePos.x), abs(leftEyePos.y)) < 0.15) {
            col = vec3(1.0);
        }
        if (min(abs(rightEyePos.x - rightEyePos.y), abs(rightEyePos.x + rightEyePos.y)) < 0.03 
            && max(abs(rightEyePos.x), abs(rightEyePos.y)) < 0.15) {
            col = vec3(1.0);
        }
    } else {
        // Normal circular eyes when not blinking
        if (leftEye < 0.15) col = vec3(1.0);
        if (rightEye < 0.15) col = vec3(1.0);
    }

    // Draw smile (white)
    vec2 smileUV = centeredUV - vec2(0.0, -0.1);
    float smile = length(smileUV);
    if (smile < 0.4 && smile > 0.3 && smileUV.y < 0.0) col = vec3(1.0);

    // Text at bottom - simple black line
    vec2 textUV = uv;
    textUV.y = textUV.y * 2.0 - 0.2; // Position at bottom
    if (textUV.y > -0.1 && textUV.y < 0.1 && // Height of text
        textUV.x > 0.2 && textUV.x < 0.8) {  // Width of text
        col = vec3(0.0); // Black text
    }

    fragColor = vec4(col, 1.0);
}
